import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _extract_text_from_pages(result: Any) -> str:
    lines: List[str] = []
    pages = getattr(result, "pages", None) or []
    for page in pages:
        for line in getattr(page, "lines", None) or []:
            content = getattr(line, "content", None)
            if content:
                lines.append(content)
    if lines:
        return "\n".join(lines).strip()

    content = getattr(result, "content", None)
    if content:
        return content.strip()

    # Fallback for dictionary-like results
    if isinstance(result, dict):
        pages = result.get("pages") or []
        for page in pages:
            for line in page.get("lines", []):
                content = line.get("content")
                if content:
                    lines.append(content)
        if lines:
            return "\n".join(lines).strip()
        content = result.get("content")
        if content:
            return str(content).strip()

    return ""


def _extract_layout_from_result(result: Any) -> Dict[str, Any]:
    layout: Dict[str, Any] = {"pages": []}
    pages = getattr(result, "pages", None) or []
    for page in pages:
        page_info: Dict[str, Any] = {
            "page_number": getattr(page, "page_number", None),
            "width": getattr(page, "width", None),
            "height": getattr(page, "height", None),
            "unit": getattr(page, "unit", None),
            "lines": [],
            "words": [],
        }
        for line in getattr(page, "lines", None) or []:
            page_info["lines"].append(
                {
                    "content": getattr(line, "content", None),
                    "polygon": getattr(line, "polygon", None),
                }
            )
        for word in getattr(page, "words", None) or []:
            page_info["words"].append(
                {
                    "content": getattr(word, "content", None),
                    "confidence": getattr(word, "confidence", None),
                    "polygon": getattr(word, "polygon", None),
                }
            )
        layout["pages"].append(page_info)

    if not layout["pages"] and isinstance(result, dict):
        for page in result.get("pages", []):
            page_info = {
                "page_number": page.get("page_number"),
                "width": page.get("width"),
                "height": page.get("height"),
                "unit": page.get("unit"),
                "lines": page.get("lines", []),
                "words": page.get("words", []),
            }
            layout["pages"].append(page_info)

    return layout


def extract_text_and_layout(image_path: str) -> Dict[str, Any]:
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    if not endpoint or not key:
        raise EnvironmentError(
            "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY must be set"
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(image_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-layout",
            analyze_request=f,
            content_type="application/octet-stream",
        )
    result = poller.result()

    return {
        "text": _extract_text_from_pages(result),
        "layout": _extract_layout_from_result(result),
    }
